<script setup>
import {computed,shallowRef} from 'vue'
import {useRoute} from 'vue-router'
import {path,strategies,fmt} from '../data'
import {openModal,session} from '../session'
import Icon from '../components/Icon.vue'
import Chart from '../components/Chart.vue'
import Coin from '../components/Coin.vue'
const route=useRoute(),style=shallowRef("aiQuant.templates.filterAll"),market=shallowRef("aiQuant.templates.filterAll"),sort=shallowRef("aiQuant.templates.sortBy.sharpe_desc")
const section=computed(()=>route.params.section),mine=computed(()=>['mine','positions'].includes(route.params.id)),isFund=computed(()=>section.value==='quant-fund')
const visible=computed(()=>strategies.filter(s=>(style.value==="aiQuant.templates.filterAll"||s.style===style.value)&&(market.value==="aiQuant.templates.filterAll"||s.market===market.value)).toSorted((a,b)=>sort.value==="aiQuant.templates.sortBy.sharpe_asc"?a.sharpe-b.sharpe:b.sharpe-a.sharpe))
const funds=[{rate:.73,days:0,min:4999,max:99999,progress:83.6},{rate:1.25,days:7,min:100000,max:499999,progress:79.8},{rate:1.79,days:15,min:500000,max:999999,progress:75.9},{rate:2.35,days:30,min:1000000,max:4999999,progress:69.6},{rate:2.93,days:60,min:5000000,max:10000000,progress:52.8},{rate:3.55,days:90,min:10000000,max:100000000,progress:43.6}]
function subscribe(s){openModal('subscribe',"quant.ui.subscribeToStrategy",{name:s.name,symbol:'USD',min:s.min,days:30,rate:.01})}
</script>
<template><div class="page-wrap quant-page">
<template v-if="!section"><div class="page-hero"><small class="page-kicker">{{ $t("aiQuant.landing.eyebrow") }}</small><h1 class="page-title" style="font-size:2.25rem">{{ $t("aiQuant.landing.title") }}</h1><p class="page-desc">{{ $t("aiQuant.landing.subtitle") }}</p></div><div class="two-cols quant-intro"><div v-for="(kind,i) in [&quot;aiQuant.landing.strategy.name&quot;,&quot;aiQuant.landing.quantFund.name&quot;]" :key="kind" class="card card-glow"><div class="coin-label"><Icon :name="i?'shield':'bot'" green/><div><small class="page-kicker">{{ $t(i?"aiQuant.landing.quantFund.kicker":"aiQuant.landing.strategy.kicker") }}</small><h2>{{ $t(kind) }}</h2></div></div><p>{{ $t(i?"aiQuant.landing.quantFund.valueProp":"aiQuant.landing.strategy.valueProp") }}</p><div style="margin-top:20px"><span class="tag-chip">{{ $t(i?"aiQuant.landing.quantFund.chipA":"aiQuant.landing.strategy.chipA") }}</span> <span class="tag-chip">{{ $t(i?"aiQuant.landing.quantFund.chipB":"aiQuant.landing.strategy.chipB") }}</span></div><RouterLink class="pill primary" :to="path(i?'/ai-quant/quant-fund':'/ai-quant/strategy')">{{ $t(i?"aiQuant.landing.quantFund.browse":"aiQuant.landing.strategy.browse") }} <Icon name="arrow-right"/></RouterLink><RouterLink class="card-footer" :to="path(i?'/ai-quant/quant-fund/positions':'/ai-quant/strategy/mine')"><span>{{ $t(i?"aiQuant.landing.quantFund.mine":"aiQuant.landing.strategy.mine") }}</span><small>{{ $t("quant.ui.private") }}{{ $t(i?"quant.ui.subscriptionsAndInterest":"quant.ui.runningInstances") }}</small></RouterLink></div></div></template>
<template v-else><nav class="subnav"><RouterLink :to="path(isFund?'/ai-quant/quant-fund':'/ai-quant/strategy')">{{ $t(isFund?"aiQuant.landing.quantFund.name":"aiQuant.nav.strategy") }}</RouterLink><RouterLink :to="path(isFund?'/ai-quant/quant-fund/positions':'/ai-quant/strategy/mine')">{{ $t(isFund?"aiQuant.landing.quantFund.mine":"aiQuant.landing.strategy.mine") }}</RouterLink></nav>
<template v-if="mine"><h1 class="page-title">{{ $t(isFund?"aiQuant.landing.quantFund.mine":"aiQuant.landing.strategy.mine") }}</h1><div class="card empty"><Icon name="bot"/><p v-if="!session.subscriptions.length">{{ $t("content.ui.no") }}{{ $t(isFund?"copytrade.myPositions.size":"aiQuant.myStrategies.subtitle") }}</p><div v-for="(s,i) in session.subscriptions" :key="i" class="summary-line">{{ $t(s.name) }}<b>{{ $t(fmt(s.amount)) }}{{ $t(" USD") }}</b><span class="positive">{{ $t(s.status) }}</span></div></div></template>
