utton></article></div></div><section id="templates" class="section-gap"><h2 style="font-size:1.5rem">{{ $t("aiQuant.nav.strategy") }}</h2><p class="section-desc">{{ $t("aiQuant.templates.subtitle") }}</p><div class="filter-row"><span class="muted">{{ $t("aiQuant.templates.filterByStyle") }}</span><button v-for="s in [&quot;aiQuant.templates.filterAll&quot;,&quot;aiQuant.style.conservative&quot;,&quot;aiQuant.style.balanced&quot;,&quot;aiQuant.style.aggressive&quot;]" :key="s" :class="{active:style===s}" @click="style=s">{{ $t(s) }}</button><span class="muted">{{ $t("aiQuant.templates.filterByMarket") }}</span><button v-for="m in [&quot;aiQuant.templates.filterAll&quot;,&quot;aiQuant.market.crypto&quot;,&quot;aiQuant.market.stock&quot;,&quot;aiQuant.market.forex&quot;,&quot;aiQuant.market.indices&quot;]" :key="m" :class="{active:market===m}" @click="market=m">{{ $t(m) }}</button><label>{{ $t("aiQuant.templates.sortBy.label") }}<select v-model="sort"><option :value="&quot;aiQuant.templates.sortBy.sharpe_desc&quot;">{{ $t("aiQuant.templates.sortBy.sharpe_desc") }}</option><option :value="&quot;aiQuant.templates.sortBy.sharpe_asc&quot;">{{ $t("aiQuant.templates.sortBy.sharpe_asc") }}</option></select></label></div><div class="three-cols"><article v-for="s in visible" :key="s.id" class="card quant-card"><h3>{{ $t(s.name) }}</h3><p><span class="tag-chip">{{ $t(s.market) }}</span> <span class="tag-chip">{{ $t(s.style) }}</span> <span class="tag-chip">{{ $t("Lv.") }}{{ $t(s.risk) }}</span></p><div class="summary-line"><div><b class="metric">{{ $t(s.sharpe.toFixed(2)) }}</b><p class="mini-label">{{ $t("aiQuant.templates.fields.sharpeRatio") }}</p></div><div><b style="font-size:1.5rem">{{ $t(s.win) }}%</b><p class="mini-label">{{ $t("aiQuant.templates.fields.winRate") }}</p></div></div><p>{{ $t(s.description) }}</p><dl class="details-list"><dt>{{ $t("quant.ui.capitalUsd") }}</dt><dd>{{ $t(fmt(s.min)) }}–100,000</dd><dt>{{ $t("aiQuant.templates.fields.period") }}</dt><dd>{{ $t("quant.ui.790Days") }}</dd><dt>{{ $t("aiQuant.templates.fields.supportedSymbols") }}</dt><dd>{{ $t(s.market==="aiQuant.market.forex"?'EURUSD / USDJPY':s.market==="aiQuant.market.stock"?'SPX500 / NAS100':'BTCUSD / ETHUSD') }}</dd></dl><small class="muted">{{ $t("quant.ui.proprietaryQuantModel1TradeDay") }}</small><button class="primary-button wide-button" @click="subscribe(s)">{{ $t("aiQuant.templates.subscribe") }}</button></article></div><p class="empty" v-if="!visible.length">{{ $t("quant.ui.noMatchingStrategyTemplates") }}</p></section></template>
</template></div></template>
<style scoped>.strategy-hero{padding:40px 0;gap:10%}.strategy-hero h1{font-size:3.5rem}.strategy-graph{align-self:center;height:380px}.strategy-graph .eyebrow{margin:0}.fund-hero{padding:56px 40px;margin-top:60px}.fund-hero .page-desc{max-width:600px}#templates{scroll-margin-top:90px}@media(max-width:900px){.strategy-hero h1{font-size:2.5rem}.strategy-hero{gap:24px}.strategy-graph{height:300px}.fund-hero{padding:32px;margin-top:30px}}@media(max-width:600px){.strategy-hero h1{font-size:2.25rem}.strategy-hero .two-cols{grid-template-columns:1fr 1fr}.strategy-graph{min-height:260px}.fund-hero{padding:24px}.fund-hero .page-title{font-size:1.75rem}}
</style>
